from itertools import product, combinations
from collections import Counter


def _route(minimum_duration, exact):
    def solve(data):
        required = data.get('required', [])
        index = {node: i for i, node in enumerate(required)}
        full = (1 << len(required)) - 1
        initial_mask = 1 << index[data['source']] if data['source'] in index else 0
        graph = [[] for _ in range(data['n'])]
        for edge in data['edges']:
            graph[edge['u']].append(edge)

        start_state = (data['source'], initial_mask, 0)
        distance = {start_state: data['start']}
        queue = [(data['start'], data['source'], initial_mask, 0)]
        while queue:
            arrival, node, mask, used = heapq.heappop(queue)
            state = (node, mask, used)
            if distance.get(state) != arrival:
                continue
            if (node == data['target'] and mask == full and
                    (not exact or used == data['coupons'])):
                return {'arrival': arrival}

            for edge in graph[node]:
                depart = max(arrival, edge['open'])
                if depart >= edge['close']:
                    continue
                options = [(edge['duration'], used)]
                if used < data['coupons']:
                    discounted = max(minimum_duration,
                                     edge['duration'] - edge.get('discount', 0))
                    options.append((discounted, used + 1))
                for duration, next_used in options:
                    next_time = depart + duration
                    if next_time > data['deadline']:
                        continue
                    next_node = edge['v']
                    next_mask = mask
                    if next_node in index:
                        next_mask |= 1 << index[next_node]
                    next_state = (next_node, next_mask, next_used)
                    if next_time < distance.get(next_state, float('inf')):
                        distance[next_state] = next_time
                        heapq.heappush(queue, (next_time, next_node,
                                               next_mask, next_used))
        return {'arrival': None}
    return solve


def _component_06(data):
    def rounded(numerator, denominator):
        if data['rounding'] == 'half_up':
            return (numerator + denominator // 2) // denominator
        return numerator // denominator

    cutoff = data.get('cutoff', 10**9)
    winners = {}
    for position, event in enumerate(data['events']):
        sequence = event.get('sequence', 0)
        if sequence > cutoff:
            continue
        event_id = event.get('id', 'anonymous:' + str(position))
        key = (sequence, event.get('revision', 0), position)
        if event_id not in winners or key > winners[event_id][0]:
            winners[event_id] = (key, event)

    balances = dict(data.get('opening', {}))
    for _, event in winners.values():
        if event.get('void', False):
            continue
        raw = event['price'] * event.get('quantity', 1)
        discount = min(10000, max(0, event.get('discount_bp', 0)))
        net = rounded(raw * (10000 - discount), 10000)
        tax = rounded(raw * event.get('tax_bp', 0), 10000)
        total = net + tax
        if event.get('kind') == 'refund':
            total = -total
        account = event.get('account', 'default')
        currency = event.get('currency', 'USD')
        key = account + '|' + currency
        balances[key] = balances.get(key, 0) + total
    return {'balances': balances}


def _component_07(data):
    packages = data['packages']
    names = sorted(packages, reverse=True)
    features = set(data.get('features', []))
    blocked = data.get('blocked', {})
    pins = data.get('pins', {})
    domains = {}
    for name in names:
        versions = sorted(row['version'] for row in packages[name]
                          if row['version'] not in blocked.get(name, []) and
                          (name not in pins or row['version'] == pins[name]))
        domains[name] = [-1] + versions

    best_vector = None
    best_assignment = None
    for values in product(*(domains[name] for name in names)):
        assignment = dict(zip(names, values))
        reachable = set()
        graph = {}
        pending = []
        valid = True

        for name, bounds in data['roots'].items():
            version = assignment[name]
            if version == -1 or not bounds[0] <= version <= bounds[1]:
                valid = False
                break
            pending.append(name)
        if not valid:
            continue

        while pending and valid:
            name = pending.pop()
            if name in reachable:
                continue
            reachable.add(name)
            version = assignment[name]
            row = next(row for row in packages[name]
                       if row['version'] == version)
            graph[name] = []
            for dep in row.get('deps', []):
                feature = dep.get('feature', '')
                if feature and feature not in features:
                    continue
                other = dep['name']
                other_version = assignment[other]
                if (other_version == -1 or not dep['min'] <= other_version <= dep['max']):
                    valid = False
                    break
                graph[name].append(other)
                pending.append(other)

        if not valid or reachable != {name for name in names if assignment[name] != -1}:
            continue

        finished = set()
        active = set()
        def visit(name):
            if name in active:
                return False
            if name in finished:
                return True
            active.add(name)
            if any(not visit(other) for other in graph.get(name, [])):
                return False
            active.remove(name)
            finished.add(name)
            return True

        if not all(visit(name) for name in reachable):
            continue
        vector = tuple(assignment[name] for name in names)
        if best_vector is None or vector > best_vector:
            best_vector = vector
            best_assignment = assignment

    if best_assignment is None:
        return {'error': 'unsatisfiable'}
    return {'versions': {name: best_assignment[name] for name in names
                         if best_assignment[name] != -1}}


def _component_08(data):
    jobs = data['jobs']
    blocked = set(data.get('blocked', []))
    mandatory = set(data.get('mandatory', []))
    options = [job for job in jobs if job['id'] not in blocked]
    best_value = None
    best_ids = None

    for selected in combinations(options, data['k']):
        ids = {job['id'] for job in selected}
        if not mandatory.issubset(ids):
            continue
        counts = Counter(job['group'] for job in selected)
        if any(not low <= counts[group] <= high
               for group, (low, high) in data.get('quotas', {}).items()):
            continue

        active_ends = []
        compatible = True
        for job in sorted(selected, key=lambda row: (row['start'], row['end'])):
            while active_ends and active_ends[0] <= job['start']:
                heapq.heappop(active_ends)
            heapq.heappush(active_ends, job['end'])
            if len(active_ends) > 2:
                compatible = False
                break
        if not compatible:
            continue

        value = sum(job['value'] for job in selected)
        selected_ids = sorted(ids)
        if (best_value is None or value > best_value or
                (value == best_value and selected_ids < best_ids)):
            best_value, best_ids = value, selected_ids

    if best_value is None:
        return {'error': 'impossible'}
    return {'selected': best_ids, 'value': best_value}


